use super::*;

/// Map newly-woken waiters to their wake actions.
pub fn plan_wakes(woken: &[Waiter], s: &CoordState) -> Vec<WakeAction> {
    woken
        .iter()
        .map(|w| WakeAction { session: w.session.clone(), deps: w.deps.clone(), prompt: wake_prompt_for(w, s) })
        .collect()
}
